import { uniqueStrings } from './unique_base.mjs';

// Basic dedup preserving order
const a = ['apple', 'banana', 'apple', 'cherry', 'banana'];
const r1 = uniqueStrings(a);
console.log('r1:', JSON.stringify(r1));
console.assert(JSON.stringify(r1) === JSON.stringify(['apple','banana','cherry']), 'basic dedup failed');

// Case sensitivity
const r2 = uniqueStrings(['a', 'A', 'a', 'B', 'b']);
console.log('r2:', JSON.stringify(r2));
console.assert(JSON.stringify(r2) === JSON.stringify(['a','A','B','b']), 'case sensitivity failed');

// Whitespace not trimmed
const r3 = uniqueStrings([' x', 'x', ' x', 'x ']);
console.log('r3:', JSON.stringify(r3));
console.assert(JSON.stringify(r3) === JSON.stringify([' x','x','x ']), 'whitespace handling failed');

// Input not mutated
const input = ['a', 'b', 'a'];
const snapshot = JSON.stringify(input);
uniqueStrings(input);
console.assert(JSON.stringify(input) === snapshot, 'input was mutated');

// Empty array
const r4 = uniqueStrings([]);
console.assert(Array.isArray(r4) && r4.length === 0, 'empty array failed');

// Returns a new array (not same reference)
const r5 = uniqueStrings(['a']);
console.assert(r5 !== ['a'], 'should return new array');

console.log('All checks passed.');
"

